def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5}
    while unseen:
        start = unseen.pop()
        stack = [start]
        comp = {start}
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p); comp.add(p); stack.append(p)
        r0 = min(r for r,c in comp); r1 = max(r for r,c in comp)
        c0 = min(c for r,c in comp); c1 = max(c for r,c in comp)
        # Fill the hollow body; the opening is in the upper edge, immediately
        # inside the right wall, and emits a leftward 2-ray above the object.
        for r in range(r0+1, r1):
            for c in range(c0+1, c1):
                if out[r][c] == 0:
                    out[r][c] = 2
        gap_col = c1 - 1
        if r0 > 0:
            for c in range(gap_col + 1):
                if out[r0-1][c] == 0:
                    out[r0-1][c] = 2
        if r0 < h and c0 <= gap_col < w and grid[r0][gap_col] == 0:
            out[r0][gap_col] = 2
    return out
